<script type="text/javascript">

    
    var BannerAd_adsViewabilityComplete = false;

    function BannerAd_removeStickyness(adWrapperElement, stickyTopElement) {
        if(!BannerAd_adsViewabilityComplete) {
            if(adWrapperElement.classList.contains("is-sticked")){
                BannerAd_animate(adWrapperElement, stickyTopElement)
            }
        }
    }

    function BannerAd_toggleStickyBackgroundOnScroll(slotData, adWrapperElement, stickyTopElement) {
        if (slotData) {
            adWrapperElement.classList.add("ads-loaded")

            const observerTop = new IntersectionObserver(function(entries) {

                    if(!BannerAd_adsViewabilityComplete) {
                        if(entries[0].intersectionRatio === 0)
                            adWrapperElement.classList.add("ads-loaded")
                        else if(entries[0].intersectionRatio === 1) {
                            adWrapperElement.classList.remove("ads-loaded")
                        }
                    }
                    else {
                        observerTop.disconnect()
                    }
                }
                ,
                { threshold: [0,1] }
            );

            observerTop.observe(stickyTopElement);
        }
    }

    function BannerAd_animate(adWrapperElement, stickyTopElement) {
        const observerTopAnimation = new IntersectionObserver(function(entries) {

                if(entries[0].intersectionRatio === 0) {
                    BannerAd_removeStickyWithAnimation(adWrapperElement)
                }
                else if(entries[0].intersectionRatio === 1) {
                    BannerAd_removeStickyWithoutAnimation(adWrapperElement)
                }

                BannerAd_adsViewabilityComplete = true
                observerTopAnimation.disconnect()
            }
            ,
            { threshold: [0,1] }
        );

        observerTopAnimation.observe(stickyTopElement);
    }

    function BannerAd_removeStickyWithAnimation(adWrapperElement) {
        adWrapperElement.classList.add("hide-animation")
        setTimeout(function(){
            adWrapperElement.classList.remove("ads-loaded")
            console.log("ads removed by viewability")
            adWrapperElement.classList.remove("is-sticked")
            adWrapperElement.classList.remove("hide-animation")
        }, 1000)
    }

    function BannerAd_removeStickyWithoutAnimation(adWrapperElement) {
        adWrapperElement.classList.remove("ads-loaded")
        adWrapperElement.classList.remove("is-sticked")
    }

    function getPage() {
        var path = window.location.pathname
        return path.split("/").slice(-2,-1)[0]
    }

    function setCurrentPageInSessionStorage() {
        window.sessionStorage.setItem("lp.ads.banner.page", getPage())
    }

    function isReloaded() {
        return window.sessionStorage.getItem("lp.ads.banner.page") === getPage()
    }

</script>
    <div id="headerpos1-sticky-top" class="adsWrapper-sticky-top"></div>
    <div id="headerpos1-wrapper" class="adsWrapper sticky is-sticked pageBlock--emplacement-storyPageHeaderAd">
        <div class="fixed-header-ad-container">
            <div class="adSpotBlock wrapCenter pageBox">
                <div id="headerpos1-slotWrapper" class="slotWrapper adSpotBlock__slotWrapper">
                    <div id="headerpos1-adSlotLppos" class="adSlot adSpotBlock__slotInner">
                    </div>
                    <script data-name="headerpos1-adSlotLppos" data-ads-meta="">
                        (function () {
                            var slotName = "headerpos1-adSlotLppos";
                            var dimensions = ["fluid",[728,90],[970,250],[970,415]];
                            var positionName = "pos1";
                            var pageBlock = "header";
                            var wrapper = "headerpos1-wrapper";
                            var stickyTop = "headerpos1-sticky-top";

                            var adUnitPath = '/' + [
                                nuglif.ngApp.globals.network,
                                nuglif.ngApp.globals.topLevelAdUnit,
                                nuglif.ngApp.globals.adUnit
                            ].join('/');

                            LPAds.createAdSpot(slotName, adUnitPath, pageBlock, positionName, dimensions);

                            if (isReloaded()) {
                                BannerAd_removeStickyWithoutAnimation(document.getElementById(wrapper))
                            }
                            else{
                                LPAds.registerSpotViewedEvent(slotName, function () {
                                    BannerAd_removeStickyness(document.getElementById(wrapper), document.getElementById(stickyTop));
                                });

                                LPAds.registerSpotReceived(slotName, function (slotData) {
                                    BannerAd_toggleStickyBackgroundOnScroll(slotData, document.getElementById(wrapper), document.getElementById(stickyTop));
                                });
                            }

                            setCurrentPageInSessionStorage()

                            function setUpNativeAdCollection() {
                                console.debug('Ads: Native Ad Collection detected for ' + slotName);
                                let slotInner = document.getElementById(slotName);
                                slotInner.parentElement.style.width = '100%';
                                slotInner.parentElement.style.maxWidth = '1290px';
                                slotInner.classList.add("adSpotBlock__slotInner--collection");
                            }

                            function setUpNativeAdSerieXtra() {
                                console.debug('Ads: Native Ad Série Xtra detected for ' + slotName);
                                let slotInner = document.getElementById(slotName)
                                slotInner.parentElement.style.width = '100%';
                                slotInner.classList.add("adSpotBlock__slotInner--serie-xtra");

                                let googleIframe = slotInner.firstElementChild.firstElementChild;
                                window.addEventListener('message', (e)=> {
                                    if (googleIframe.contentWindow === e.source){
                                        if(e.data.nbArticles) {
                                            let title = document.createElement("div")
                                            let nbArticles = document.createElement("div")
                                            title.innerHTML = "Série commanditée"
                                            nbArticles.innerHTML = e.data.nbArticles + " articles"
                                            let header = document.createElement("div")
                                            header.classList.add("adSpotBlock__slotInnerHeader")
                                            header.appendChild(title)
                                            header.appendChild(nbArticles)
                                            slotInner.prepend(header)
                                        }
                                    }
                                })
                            }

                            LPAds.registerSpotRenderEnded(slotName, function(slotData) {
                                var wrapperElement = document.getElementById(wrapper);
                                var container = wrapperElement ? wrapperElement.querySelector('.fixed-header-ad-container') : null;

                                if (container) {
                                    console.debug('Ads: Fixed Header Ad detected for ' + slotName);

                                    var isEmpty = !slotData || slotData.isEmpty === true || slotData.isAdEmpty === true;

                                    if (isEmpty) {
                                        console.debug('Ads: Fixed Header Ad is empty for ' + slotName);
                                        collapseAdContainer(container);
                                    } else {
                                        var finalHeight = 0;

                                        if (Array.isArray(slotData.size) && slotData.size.length >= 2) {
                                            finalHeight = slotData.size[1];
                                        } else if (slotData.height) {
                                            finalHeight = slotData.height;
                                        }

                                        if (finalHeight > 0) {
                                            applyAdHeight(container, finalHeight);
                                        } else {
                                            var attempts = 0;
                                            var checkInterval = setInterval(function() {
                                                attempts++;
                                                var currentSlot = document.getElementById(slotName);
                                                var currentHeight = currentSlot ? currentSlot.offsetHeight : 0;

                                                console.debug('Ads: Fixed Header Ad height check attempt ' + attempts);

                                                if (currentHeight > 5) {
                                                    applyAdHeight(container, currentHeight);
                                                    clearInterval(checkInterval);
                                                } else if (attempts > 30) {
                                                    console.debug('Ads: Timeout reached, hiding container');
                                                    collapseAdContainer(container);
                                                    clearInterval(checkInterval);
                                                }
                                            }, 100);
                                        }
                                    }
                                }

                                function collapseAdContainer(el) {
                                    el.style.minHeight = "0px";
                                    el.style.height = "0px";
                                    el.style.display = "none";
                                    el.style.background = "transparent";
                                }

                                function applyAdHeight(el, h) {
                                    el.style.minHeight = h + "px";
                                    el.style.height = "auto";
                                    el.style.background = "transparent";
                                    el.classList.add("ad-loaded");
                                }

                                if (slotData) {
                                   if (LPAds.isNativeAdSerieXtra(slotData.creativeTemplateId)) {
                                        setUpNativeAdSerieXtra();
                                    } else if (LPAds.isNativeAdCollection(slotData.creativeTemplateId)) {
                                        setUpNativeAdCollection();
                                   }
                                }
                            });

                            LPAds.displayAdSpot(slotName);
                        })()
                    </script>
                </div>
            </div>
        </div>
        <script>
            (function() {
                var timeoutDuration = 4000;
                var wrapperId = "headerpos1-wrapper";
                var adSlotId = "headerpos1-adSlotLppos";

                setTimeout(function() {
                    var wrapper = document.getElementById(wrapperId);
                    var container = wrapper ? wrapper.querySelector('.fixed-header-ad-container') : null;
                    var slotElement = document.getElementById(adSlotId);

                    if (container) {
                        var hasIframe = slotElement && slotElement.querySelector('iframe');
                        var isLoaded = container.classList.contains('ad-loaded');

                        if (!hasIframe && !isLoaded) {
                            console.debug('Ads: Fixed Header Ad is empty for ' + adSlotId + ', closing.');
                            container.style.transition = "height 0.3s ease-out";
                            container.style.height = "0px";
                            container.style.minHeight = "0px";
                            setTimeout(function() {
                                container.style.display = "none";
                            }, 300);
                        }
                    }
                }, timeoutDuration);
            })();
        </script>
