                function setUpNativeAdCollection() {
                    console.debug('Ads: Native Ad Collection detected for ' + slotName);
                    let slotInner = document.getElementById(slotName);
                    slotInner.parentElement.style.width = '100%';
                    slotInner.parentElement.style.maxWidth = '1290px';
                    slotInner.classList.add("adSpotBlock__slotInner--collection");
                }

                function setUpNativeAdSerieXtra() {
                    console.debug('Ads: Native Ad Série Xtra detected for ' + slotName);
                    let slotInner = document.getElementById(slotName);
                    slotInner.parentElement.style.width = '100%';
                    slotInner.classList.add("adSpotBlock__slotInner--serie-xtra");

                    let googleIframe = slotInner.firstElementChild.firstElementChild;
                    window.addEventListener('message', (e)=> {
                        if (googleIframe.contentWindow === e.source){
                            if(e.data.nbArticles) {
                                let title = document.createElement("div")
                                let nbArticles = document.createElement("div")
                                title.innerHTML = "Série commanditée"
                                nbArticles.innerHTML = e.data.nbArticles + " articles"
                                let header = document.createElement("div")
